contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call run specifying an amount to send and an unlockTime to pass to Put.
    // msg.sender for calls to c will be this test contract.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // read balance in c for this contract's address before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // call Put with value 'amount'
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: If the Put call did NOT revert, then
        //  - the stored balance for this address increased by exactly 'amount'
        //  - the contract's Ether balance increased by exactly 'amount'
        // If it reverted, nothing is required (call may revert). This asserts that Put cannot silently decrease the stored balance.
        assert(reverted || (afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call Collect with a given amount; we send no Ether with this call.
    // We assert a general invariant: if Collect does not revert, then both the stored Acc balance
    // for this test contract and the contract's Ether balance have decreased by at least _am.
    function run(uint _am) public payable {
        // no precondition on _am; we only call Collect (no value sent)

        // observe before values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // call Collect and catch revert
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call did not revert, then at the end:
        //  - the recorded balance for this address cannot have increased; specifically it must be <= beforeBalance
        //  - the recorded balance must have decreased by at least _am (or, if underflow prevented, be <= beforeBalance - _am)
        //  - the contract's Ether balance must be <= beforeContractBal - _am (i.e., decreased by at least _am)
        // We express these as safe comparisons avoiding underflow in arithmetic in the assert.
        assert(reverted || (
            afterBalance <= beforeBalance &&
            // If beforeBalance >= _am then afterBalance <= beforeBalance - _am, else afterBalance <= beforeBalance (no requirement to go negative)
            (beforeBalance >= _am ? afterBalance <= beforeBalance - _am : afterBalance <= beforeBalance) &&
            // Similarly for contract balance: it must have decreased by at least _am when possible
            (beforeContractBal >= _am ? afterContractBal <= beforeContractBal - _am : afterContractBal <= beforeContractBal)
        ));
    }

    // accept Ether if sent back by C during Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
