contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will test both Put (via explicit Put call) and Collect behaviors in one run.
    // params:
    // putAmount - Ether to send to Put
    // unlockTime - parameter passed to Put
    // collectAmount - amount to attempt to Collect
    // doCollect - if true, attempt a Collect after Put
    function run(uint putAmount, uint unlockTime, uint collectAmount, bool doCollect) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");
        // read pre-state observed through public getters
        uint beforeContractBal = address(c).balance;
        // Acc is public mapping, getter has signature Acc(address) -> (uint unlockTime, uint balance)
        (, uint beforeAccBal) = c.Acc(address(this));

        // perform Put by calling fallback or Put directly with value
        // Use explicit Put to exercise the main function
        c.Put{value: putAmount}(unlockTime);

        // read post-put state
        uint afterContractBal = address(c).balance;
        (, uint afterAccBal) = c.Acc(address(this));

        // If putAmount >= 0 then afterAccBal >= beforeAccBal and contract balance increased accordingly
        // Because Solidity guarantees no negative underflow, we state non-decreasing property
        // Now optionally attempt Collect and observe whether it reverted or not
        bool collectReverted = false;
        if (doCollect) {
            // ensure we have enough balance in this contract to receive refund if Collect pays out
            // (Collect sends to msg.sender which is this test contract)
            try c.Collect{value: 0}(collectAmount) {
                collectReverted = false;
            } catch {
                collectReverted = true;
            }
        }

        uint finalContractBal = address(c).balance;
        (, uint finalAccBal) = c.Acc(address(this));

        // General rule asserted:
        // 1) After Put, the account balance observed via Acc is at least previous balance.
        // 2) The contract's balance increased by exactly (afterAccBal - beforeAccBal).
        // 3) If Collect succeeded (did not revert) then both account balance and contract balance decreased by exactly collectAmount
        //    and Collect only succeeds when beforeAccBal+putAmount >= c.MinSum and beforeAccBal+putAmount >= collectAmount and block time conditions hold.
        // We cannot refer to block.timestamp or MinSum directly in assertion, so we express observable invariants:
        // - afterAccBal >= beforeAccBal
        // - (afterContractBal - beforeContractBal) == (afterAccBal - beforeAccBal)
        // - If doCollect and not collectReverted then (finalAccBal + collectAmount == afterAccBal) and (afterContractBal == finalContractBal + collectAmount)

        assert(
            // non-decreasing account balance after Put
            afterAccBal >= beforeAccBal
            // contract balance changed in same way as account balance
            && (afterContractBal - beforeContractBal) == (afterAccBal - beforeAccBal)
            // if collect attempted and succeeded, balances reflect transfer of collectAmount
            && (
                !doCollect || collectReverted || (
                    finalAccBal + collectAmount == afterAccBal
                    && afterContractBal == finalContractBal + collectAmount
                )
            )
        );
    }

    // receive to accept refunds from Collect
    receive() external payable {}
}

