contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) put some funds into c under this contract's address using Put (via fallback or Put),
    // 2) record balances and Acc before Collect, 3) attempt Collect of a chosen amount, capturing revert,
    // 4) assert the general invariant described in property_summary.

    receive() external payable {}

    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");
        // Ensure we send exactly putAmount to contract. Use Put via calling fallback which calls Put(0).
        // But Put is public, so call it directly with chosen unlockTime.
        // First, call Put with putAmount and unlockTime to set up the account under this contract (msg.sender becomes InvMutTest when calling c).
        c.Put{value: putAmount}(unlockTime);

        // Read observable before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeAddrBal = address(c).balance;
        uint minSum = c.MinSum();

        // Try to Collect collectAmount and capture whether it reverted
        bool reverted;
        // Ensure contract has enough balance to attempt sending; collect will withdraw from c to this contract
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterAddrBal = address(c).balance;

        // Now assert the general rule.
        // If Collect succeeded (not reverted) then:
        //   - prior balance >= minSum
        //   - prior balance >= collectAmount
        //   - block.timestamp > prior unlockTime  (we cannot read block.timestamp at time of c call here, but we can compare unlock times: when Collect succeeded, c would only allow if block.timestamp > acc.unlockTime; since we can't observe block.timestamp inside c at that time, we instead assert that if Collect succeeded then beforeUnlock < block.timestamp (current time >= that at point of assertion), which is a necessary condition for success because Collect checks block.timestamp>acc.unlockTime.
        //   - afterBal == beforeBal - collectAmount
        //   - afterAddrBal == beforeAddrBal - collectAmount
        // If Collect reverted, none of those decreases hold; we assert the contraposition: if any of the three preconditions (beforeBal<minSum or beforeBal<collectAmount or beforeUnlock>=block.timestamp) holds then Collect must have reverted.

        // Compose the logical assertion combining both directions. We must express it as a single assert condition.
        bool preconditionsHoldForSuccess = (beforeBal >= minSum) && (beforeBal >= collectAmount) && (beforeUnlock < block.timestamp);
        bool balancesDecreasedProperly = (!reverted) ? (afterBal + collectAmount == beforeBal && afterAddrBal + collectAmount == beforeAddrBal) : (afterBal == beforeBal && afterAddrBal == beforeAddrBal);

        // Final combined rule:
        // - If preconditionsHoldForSuccess then Collect must not revert and balances decreased exactly by collectAmount.
        // - If Collect did not revert then preconditionsHoldForSuccess must have been true and balances decreased exactly by collectAmount.
        // This is equivalent to: balancesDecreasedProperly AND (preconditionsHoldForSuccess == (!reverted)).
        assert(balancesDecreasedProperly && (preconditionsHoldForSuccess == (!reverted)));
    }
}

contract InvMutTest {
