    // receive to accept funds when Collect sends Ether back
    receive() external payable {}

    // params: unlockTime for Put, putAmount to send with Put
    function run(uint unlockTime, uint putAmount) public payable {
        // require this test contract has enough Ether to send
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Read observables before Put
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeAddrBal = address(c).balance;

        // Call Put sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // Read observables after Put
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterAddrBal = address(c).balance;

        // General rule to assert:
        // - Put must increase the contract balance by exactly putAmount
        // - The recorded per-address balance must increase by exactly putAmount
        // - The unlockTime stored becomes max(unlockTime, block.timestamp), which is >= beforeUnlock
        // - To avoid false failures from integer overflow in stored balance, require that beforeBal + putAmount >= beforeBal (i.e., no overflow) — this is the precondition we check and include in the assertion so the property is universal only when no overflow occurs.

        // Compose the assertion as a single boolean expression over observed values.
        bool noOverflow = (beforeBal + putAmount) >= beforeBal;
        bool addrBalanceIncreased = (afterAddrBal == beforeAddrBal + putAmount);
        bool accBalanceIncreased = (afterBal == beforeBal + putAmount);
        bool unlockNonDecreasing = (afterUnlock >= beforeUnlock);
        // Also ensure stored unlock was set to at least the provided unlockTime or to block.timestamp.
        // afterUnlock should be either >= unlockTime or >= block.timestamp; equivalently: afterUnlock >= (unlockTime>block.timestamp?unlockTime:block.timestamp)
        uint expectedMinUnlock = unlockTime > block.timestamp ? unlockTime : block.timestamp;
        bool unlockSetCorrectly = (afterUnlock >= expectedMinUnlock);

        assert(noOverflow && addrBalanceIncreased && accBalanceIncreased && unlockNonDecreasing && unlockSetCorrectly);
    }
}

