    constructor(C _c) { c = _c; }

    // accept Ether when Collect sends funds
    receive() external payable {}

    // params:
    // initialPut - amount to deposit into c for this test (must be >= MinSum so Collect can succeed)
    // collectAmt - amount to attempt to collect
    // unlockTime - unlock timestamp to set via Put (should be in past so Collect can succeed immediately if desired)
    function run(uint initialPut, uint collectAmt, uint unlockTime) public payable {
        // ensure this test contract has enough Ether to seed the Put call
        require(address(this).balance >= initialPut, "insufficient test balance");

        // Seed the contract by calling Put to deposit initialPut for this test contract
        c.Put{value: initialPut}(unlockTime);

        // Read observables before Collect
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeAddrBal = address(c).balance;

        // Try to Collect collectAmt and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after Collect attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterAddrBal = address(c).balance;

        // The property to assert (single general rule):
        // If Collect did not revert then:
        //  - beforeBal >= collectAmt (Collect only sends when balance>=_am)
        //  - block.timestamp > beforeUnlock (Collect only succeeds when unlocked)
        //  - beforeBal >= c.MinSum() (Collect only succeeds when balance>=MinSum)
        //  - afterBal == beforeBal - collectAmt
        //  - afterAddrBal == beforeAddrBal - collectAmt
        // We read MinSum via its public getter implicitly as c.MinSum().

        // Compose the assertion
        uint minSum = c.MinSum();
        bool conditionsHoldIfNotReverted = true;
        if (!reverted) {
            bool balSufficient = (beforeBal >= collectAmt);
            bool unlocked = (block.timestamp > beforeUnlock);
            bool meetsMin = (beforeBal >= minSum);
            bool accUpdated = (afterBal == beforeBal - collectAmt);
            bool addrUpdated = (afterAddrBal == beforeAddrBal - collectAmt);
            conditionsHoldIfNotReverted = balSufficient && unlocked && meetsMin && accUpdated && addrUpdated;
        }

        // The assert must be a general rule over inputs/observations: if Collect succeeded then the listed conditions hold
        assert(reverted || conditionsHoldIfNotReverted);
    }
}

