        uint afterAccBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // Basic expected effect of Put: recorded balance did not decrease and contract balance increased by putAmount
        // (we don't assert here; just record values for later)

        // Attempt Collect and capture revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final observed values
        uint finalAccBalance = c.Acc(address(this)).balance;
        uint finalContractBalance = address(c).balance;

        // GENERAL ASSERTION:
        // If Collect did not revert then:
        //  - finalAccBalance = afterAccBalance - collectAmount (so the recorded balance decreased by exactly collectAmount)
        //  - finalContractBalance = afterContractBalance - collectAmount (contract sent out collectAmount)
        // If Collect reverted then no balances changed by Collect (finalAccBalance == afterAccBalance and finalContractBalance == afterContractBalance).
        // Additionally, Collect cannot increase the recorded balance: finalAccBalance <= afterAccBalance always.

        assert(
            // invariant: recorded balance never increased compared to afterAccBalance
            finalAccBalance <= afterAccBalance
            && (
                // case: Collect succeeded
                (!reverted && finalAccBalance + collectAmount == afterAccBalance && finalContractBalance + collectAmount == afterContractBalance)
                // case: Collect reverted
                || (reverted && finalAccBalance == afterAccBalance && finalContractBalance == afterContractBalance)
            )
        );
    }

    // allow receiving refunds when Collect sends ether to this test contract (not used here but safe)
    receive() external payable {}
}

