contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: collect amount to request, and a prior deposit amount and unlockTime to set up state
    function run(uint priorPut, uint putUnlockTime, uint collectAmount) public payable {
        // fund this contract so it can perform Put
        require(address(this).balance >= priorPut, "insufficient balance for put");

        // setup: perform a Put so that Acc[this] may have some balance and unlockTime
        bool putReverted;
        try c.Put{value: priorPut}(putUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // observe before Collect
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observe after
        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General invariant:
        // - Put may have reverted; if it reverted then nothing observable should have changed from that call.
        // - For Collect: if it reverted then Acc balance and contract balance remain equal to before values.
        //   If it did not revert then the decrease in Acc[this].balance equals the decrease in address(c).balance,
        //   and that decrease is <= beforeAccBalance (i.e. it cannot transfer more than the recorded balance).
        assert(
            (
                putReverted
                ? (afterAccBalance == beforeAccBalance && afterContractBalance == beforeContractBalance && afterUnlock == beforeUnlock)
                : true
            )
            && (
                collectReverted
                ? (afterAccBalance == beforeAccBalance && afterContractBalance == beforeContractBalance)
                : (
                    // collect succeeded: the two balances must have decreased by the same amount, and not below zero relative to beforeAccBalance
                    beforeAccBalance >= afterAccBalance
                    && beforeContractBalance >= afterContractBalance
                    && (beforeAccBalance - afterAccBalance) == (beforeContractBalance - afterContractBalance)
                    && (beforeAccBalance - afterAccBalance) <= beforeAccBalance
                )
            )
        );
    }

    // allow receiving Ether if needed
    receive() external payable {}
}
